1	import { lazy, Suspense } from "react";
2	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
3	import { ThemeProvider } from "next-themes";
4	import { BrowserRouter, Route, Routes } from "react-router-dom";
5	import { Toaster as Sonner } from "@/components/ui/sonner";
6	import { Toaster } from "@/components/ui/toaster";
7	import { TooltipProvider } from "@/components/ui/tooltip";
8	import { AuthProvider } from "@/contexts/AuthContext";
9	import { ProtectedRoute } from "@/components/ProtectedRoute";
10	import { AdminRoute } from "@/components/AdminRoute";
11	import { AppLayout } from "@/components/AppLayout";
12	import Dashboard from "@/pages/Dashboard";
13	import Scan from "@/pages/Scan";
14	import Reports from "@/pages/Reports";
15	import AuditReport from "@/pages/AuditReport";
16	import Integrations from "@/pages/Integrations";
17	import SettingsPage from "@/pages/Settings";
18	import Pricing from "@/pages/Pricing";
19	import Landing from "@/pages/Landing";
20	import Login from "@/pages/Login";
21	import Signup from "@/pages/Signup";
22	import AuthCallback from "@/pages/AuthCallback";
23	import ForgotPassword from "@/pages/ForgotPassword";
24	import ResetPassword from "@/pages/ResetPassword";
25	import Privacy from "@/pages/Privacy";
26	import Terms from "@/pages/Terms";
27	import NotFound from "@/pages/NotFound";
28	
29	// ── Admin routes (lazy loaded) ────────────────────────────────
30	const AdminLayout = lazy(() =>
31	  import("@/components/AdminLayout").then((m) => ({ default: m.AdminLayout }))
32	);
33	const AdminDashboard = lazy(() => import("@/pages/admin/AdminDashboard"));
34	const AdminUsers = lazy(() => import("@/pages/admin/Users"));
35	const AdminUserDetail = lazy(() => import("@/pages/admin/UserDetail"));
36	const AdminAuditLog = lazy(() => import("@/pages/admin/AuditLog"));
37	const AdminScans = lazy(() => import("@/pages/admin/Scans"));
38	const AdminBilling = lazy(() => import("@/pages/admin/Billing"));
39	const AdminSystem = lazy(() => import("@/pages/admin/System"));
40	const AdminFeatureFlags = lazy(() => import("@/pages/admin/FeatureFlags"));
41	const AdminIntegrations = lazy(() => import("@/pages/admin/Integrations"));
42	const AdminSupport = lazy(() => import("@/pages/admin/Support"));
43	
44	function AdminLoadingSpinner() {
45	  return (
46	    <div className="flex min-h-screen items-center justify-center bg-background">
47	      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
48	    </div>
49	  );
50	}
51	
52	const queryClient = new QueryClient({
53	  defaultOptions: {
54	    queries: {
55	      staleTime: 1000 * 60 * 2,
56	      gcTime: 1000 * 60 * 10,
57	      retry: (failureCount, error) => {
58	        const msg = error instanceof Error ? error.message : "";
59	        if (msg.includes("401") || msg.includes("403")) return false;
60	        return failureCount < 2;
61	      },
62	      refetchOnWindowFocus: false,
63	    },
64	    mutations: { retry: 0 },
65	  },
66	});
67	
68	const App = () => (
69	  <ThemeProvider attribute="class" defaultTheme="light" enableSystem={false}>
70	    <QueryClientProvider client={queryClient}>
71	      <TooltipProvider>
72	        <Toaster />
73	        <Sonner />
74	      <BrowserRouter>
75	        <AuthProvider>
76	          <Routes>
77	            {/* Public routes */}
78	            <Route path="/" element={<Landing />} />
79	            <Route path="/login" element={<Login />} />
80	            <Route path="/signup" element={<Signup />} />
81	            <Route path="/auth/callback" element={<AuthCallback />} />
82	            <Route path="/forgot-password" element={<ForgotPassword />} />
83	            <Route path="/reset-password" element={<ResetPassword />} />
84	            <Route path="/pricing" element={<Pricing />} />
85	            <Route path="/privacy" element={<Privacy />} />
86	            <Route path="/terms" element={<Terms />} />
87	
88	            {/* Protected app routes */}
89	            <Route element={<ProtectedRoute />}>
90	              <Route element={<AppLayout />}>
91	                <Route path="/dashboard" element={<Dashboard />} />
92	                <Route path="/scan" element={<Scan />} />
93	                <Route path="/reports" element={<Reports />} />
94	                <Route path="/reports/:id" element={<AuditReport />} />
95	                <Route path="/integrations" element={<Integrations />} />
96	                <Route path="/settings" element={<SettingsPage />} />
97	              </Route>
98	
99	              {/* Admin routes — nested inside ProtectedRoute, guarded by AdminRoute */}
100	              <Route element={<AdminRoute />}>
101	                <Route
102	                  path="/admin"
103	                  element={
104	                    <Suspense fallback={<AdminLoadingSpinner />}>
105	                      <AdminLayout />
106	                    </Suspense>
107	                  }
108	                >
109	                  <Route
110	                    index
111	                    element={
112	                      <Suspense fallback={<AdminLoadingSpinner />}>
113	                        <AdminDashboard />
114	                      </Suspense>
115	                    }
116	                  />
117	                  <Route
118	                    path="users"
119	                    element={
120	                      <Suspense fallback={<AdminLoadingSpinner />}>
121	                        <AdminUsers />
122	                      </Suspense>
123	                    }
124	                  />
125	                  <Route
126	                    path="users/:userId"
127	                    element={
128	                      <Suspense fallback={<AdminLoadingSpinner />}>
129	                        <AdminUserDetail />
130	                      </Suspense>
131	                    }
132	                  />
133	                  <Route
134	                    path="audit-log"
135	                    element={
136	                      <Suspense fallback={<AdminLoadingSpinner />}>
137	                        <AdminAuditLog />
138	                      </Suspense>
139	                    }
140	                  />
141	                  <Route
142	                    path="scans"
143	                    element={
144	                      <Suspense fallback={<AdminLoadingSpinner />}>
145	                        <AdminScans />
146	                      </Suspense>
147	                    }
148	                  />
149	                  <Route
150	                    path="billing"
151	                    element={
152	                      <Suspense fallback={<AdminLoadingSpinner />}>
153	                        <AdminBilling />
154	                      </Suspense>
155	                    }
156	                  />
157	                  <Route
158	                    path="system"
159	                    element={
160	                      <Suspense fallback={<AdminLoadingSpinner />}>
161	                        <AdminSystem />
162	                      </Suspense>
163	                    }
164	                  />
165	                  <Route
166	                    path="flags"
167	                    element={
168	                      <Suspense fallback={<AdminLoadingSpinner />}>
169	                        <AdminFeatureFlags />
170	                      </Suspense>
171	                    }
172	                  />
173	                  <Route
174	                    path="integrations"
175	                    element={
176	                      <Suspense fallback={<AdminLoadingSpinner />}>
177	                        <AdminIntegrations />
178	                      </Suspense>
179	                    }
180	                  />
181	                  <Route
182	                    path="support"
183	                    element={
184	                      <Suspense fallback={<AdminLoadingSpinner />}>
185	                        <AdminSupport />
186	                      </Suspense>
187	                    }
188	                  />
189	                </Route>
190	              </Route>
191	            </Route>
192	
193	            <Route path="*" element={<NotFound />} />
194	          </Routes>
195	        </AuthProvider>
196	      </BrowserRouter>
197	      </TooltipProvider>
198	    </QueryClientProvider>
199	  </ThemeProvider>
200	);
201	
202	export default App;
203

1	import {
2	  createContext,
3	  useContext,
4	  useEffect,
5	  useState,
6	  useCallback,
7	  type ReactNode,
8	} from "react";
9	import type { User, AuthError } from "@supabase/supabase-js";
10	import supabase from "@/lib/supabase";
11	import type { UserProfile } from "@/types/index";
12	
13	// ── Types ─────────────────────────────────────────────────────
14	
15	interface AuthContextValue {
16	  user: User | null;
17	  profile: UserProfile | null;
18	  loading: boolean;
19	  signIn: (email: string, password: string) => Promise<{ error: AuthError | null }>;
20	  signUp: (
21	    email: string,
22	    password: string,
23	    fullName: string
24	  ) => Promise<{ error: AuthError | null }>;
25	  signInWithGoogle: () => Promise<{ error: AuthError | null }>;
26	  signOut: () => Promise<void>;
27	  refreshProfile: () => Promise<void>;
28	}
29	
30	// ── Context ───────────────────────────────────────────────────
31	
32	const AuthContext = createContext<AuthContextValue | null>(null);
33	
34	// ── Provider ──────────────────────────────────────────────────
35	
36	export function AuthProvider({ children }: { children: ReactNode }) {
37	  const [user, setUser] = useState<User | null>(null);
38	  const [profile, setProfile] = useState<UserProfile | null>(null);
39	  const [loading, setLoading] = useState(true);
40	
41	  const fetchProfile = useCallback(async (userId: string) => {
42	    const { data, error } = await supabase
43	      .from("profiles")
44	      .select(
45	        "id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, role, is_banned, created_at, billing_cycle_end"
46	      )
47	      .eq("id", userId)
48	      .single();
49	
50	    if (error) {
51	      console.error("Failed to fetch profile:", error.message);
52	      setProfile(null);
53	      return;
54	    }
55	
56	    setProfile(data as UserProfile);
57	  }, []);
58	
59	  const refreshProfile = useCallback(async () => {
60	    if (!user) return;
61	    await fetchProfile(user.id);
62	  }, [user, fetchProfile]);
63	
64	  useEffect(() => {
65	    // Resolve initial session without waiting for the listener
66	    supabase.auth.getSession().then(({ data: { session } }) => {
67	      setUser(session?.user ?? null);
68	      if (session?.user) {
69	        fetchProfile(session.user.id).finally(() => setLoading(false));
70	      } else {
71	        setLoading(false);
72	      }
73	    });
74	
75	    const {
76	      data: { subscription },
77	    } = supabase.auth.onAuthStateChange((_event, session) => {
78	      setUser(session?.user ?? null);
79	      if (session?.user) {
80	        fetchProfile(session.user.id);
81	      } else {
82	        setProfile(null);
83	      }
84	    });
85	
86	    return () => subscription.unsubscribe();
87	  }, [fetchProfile]);
88	
89	  // ── Auth actions ─────────────────────────────────────────────
90	
91	  const signIn = async (email: string, password: string) => {
92	    const { error } = await supabase.auth.signInWithPassword({ email, password });
93	    return { error };
94	  };
95	
96	  const signUp = async (email: string, password: string, fullName: string) => {
97	    const { error } = await supabase.auth.signUp({
98	      email,
99	      password,
100	      options: {
101	        data: { full_name: fullName },
102	        emailRedirectTo: `${window.location.origin}/auth/callback`,
103	      },
104	    });
105	    return { error };
106	  };
107	
108	  const signInWithGoogle = async () => {
109	    const { error } = await supabase.auth.signInWithOAuth({
110	      provider: "google",
111	      options: {
112	        redirectTo: `${window.location.origin}/auth/callback`,
113	      },
114	    });
115	    return { error };
116	  };
117	
118	  const signOut = async () => {
119	    await supabase.auth.signOut();
120	    setUser(null);
121	    setProfile(null);
122	  };
123	
124	  return (
125	    <AuthContext.Provider
126	      value={{
127	        user,
128	        profile,
129	        loading,
130	        signIn,
131	        signUp,
132	        signInWithGoogle,
133	        signOut,
134	        refreshProfile,
135	      }}
136	    >
137	      {children}
138	    </AuthContext.Provider>
139	  );
140	}
141	
142	// ── Hook ──────────────────────────────────────────────────────
143	
144	export function useAuth(): AuthContextValue {
145	  const ctx = useContext(AuthContext);
146	  if (!ctx) {
147	    throw new Error("useAuth must be used inside <AuthProvider>");
148	  }
149	  return ctx;
150	}

